import React, { useState } from 'react';
import api from '../api';

const AuthModal = ({ onAuthSuccess, showToast }) => {
    const [isRegister, setIsRegister] = useState(false);
    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('client@ticketflow.ro');
    const [password, setPassword] = useState('client123');
    const [role, setRole] = useState('CLIENT');
    const [loading, setLoading] = useState(false);

    const quickFill = (demoEmail, demoPwd) => {
        setIsRegister(false);
        setEmail(demoEmail);
        setPassword(demoPwd);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            const endpoint = isRegister ? '/auth/register' : '/auth/login';
            const payload = isRegister ? { fullName, email, password, role } : { email, password };
            const res = await api.post(endpoint, payload);
            localStorage.setItem('tf_token', res.data.token);
            localStorage.setItem('tf_user', JSON.stringify(res.data.user));
            onAuthSuccess(res.data.user);
            showToast(`Signed in as ${res.data.user.fullName} (${res.data.user.role})`, 'success');
        } catch (err) {
            showToast(err.response?.data?.message || 'Authentication failed', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 relative">
            <div className="spatial-canvas">
                <div className="spatial-orb-1"></div>
                <div className="spatial-orb-2"></div>
                <div className="spatial-orb-3"></div>
            </div>

            <div className="relative z-10 max-w-md w-full liquid-glass rounded-[32px] p-7 sm:p-9 space-y-6">
                <div className="flex flex-col items-center text-center space-y-2">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-b from-white/25 to-white/5 border border-white/30 flex items-center justify-center shadow-lg text-2xl">
                        🎟️
                    </div>
                    <div className="space-y-1">
                        <h1 className="text-2xl font-bold tracking-tight text-white">TicketFlow</h1>
                        <p className="text-xs text-white/60 font-medium">Spatial Venue Access &amp; Smart Ticketing</p>
                    </div>
                </div>

                {/* Apple Segmented Quick-Fill Selector */}
                <div className="liquid-well rounded-2xl p-2 space-y-2">
                    <p className="text-[10px] font-mono uppercase tracking-widest text-white/45 text-center">Instant Demo Identities</p>
                    <div className="grid grid-cols-3 gap-1.5">
                        <button type="button" onClick={() => quickFill('client@ticketflow.ro', 'client123')} className={`py-2 rounded-xl text-xs font-semibold transition ${email === 'client@ticketflow.ro' && !isRegister ? 'bg-white/20 text-white shadow-sm border border-white/25' : 'text-white/60 hover:text-white'}`}>
                            Client
                        </button>
                        <button type="button" onClick={() => quickFill('organizer@ticketflow.ro', 'org123')} className={`py-2 rounded-xl text-xs font-semibold transition ${email === 'organizer@ticketflow.ro' && !isRegister ? 'bg-white/20 text-white shadow-sm border border-white/25' : 'text-white/60 hover:text-white'}`}>
                            Organizer
                        </button>
                        <button type="button" onClick={() => quickFill('admin@ticketflow.ro', 'admin123')} className={`py-2 rounded-xl text-xs font-semibold transition ${email === 'admin@ticketflow.ro' && !isRegister ? 'bg-white/20 text-white shadow-sm border border-white/25' : 'text-white/60 hover:text-white'}`}>
                            Admin
                        </button>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {isRegister && (
                        <>
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Full Name</label>
                                <input required type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="Alexandru Popescu" className="w-full px-4 py-3 rounded-2xl liquid-well text-sm text-white placeholder-white/30 focus:outline-none focus:border-white/40 transition" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Account Role</label>
                                <select value={role} onChange={(e) => setRole(e.target.value)} className="w-full px-4 py-3 rounded-2xl liquid-well text-sm text-white focus:outline-none focus:border-white/40 transition">
                                    <option value="CLIENT" className="bg-slate-900">Client (Wallet &amp; Booking)</option>
                                    <option value="ORGANIZER" className="bg-slate-900">Organizer (Events &amp; Analytics)</option>
                                </select>
                            </div>
                        </>
                    )}

                    <div>
                        <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Apple ID / Email</label>
                        <input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full px-4 py-3 rounded-2xl liquid-well text-sm text-white focus:outline-none focus:border-white/40 transition" />
                    </div>

                    <div>
                        <label className="block text-xs font-medium text-white/70 mb-1.5 pl-1">Password</label>
                        <input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full px-4 py-3 rounded-2xl liquid-well text-sm text-white focus:outline-none focus:border-white/40 transition" />
                    </div>

                    <button disabled={loading} type="submit" className="w-full py-3.5 rounded-full glass-pill-btn font-bold text-sm mt-2">
                        {loading ? 'Verifying...' : isRegister ? 'Create Spatial ID' : 'Continue'}
                    </button>
                </form>

                <div className="text-center pt-3 border-t border-white/10">
                    <button type="button" onClick={() => setIsRegister(!isRegister)} className="text-xs text-white/70 hover:text-white font-medium transition">
                        {isRegister ? 'Already have an account? Sign In' : 'New to TicketFlow? Create Account'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AuthModal;
